import { describe, expect, it } from 'vitest';
import { parseLog, selectFields, supportedLogFormats } from '../src/index';

const adif = [
  'Generated by test',
  '<ADIF_VER:5>3.1.4<EOH>',
  '<CALL:5>DL1AA<QSO_DATE:8>20261010<TIME_ON:4>1234<EOR>',
  '<CALL:6>F1BÁR<QSO_DATE:8>20261010<TIME_ON:4>1300<EOR>',
].join('');

describe('log parsing', () => {
  it('lists ADIF fields and respects UTF-8 byte lengths', () => {
    expect(selectFields(adif)).toEqual(['CALL', 'QSO_DATE', 'TIME_ON']);
    expect(parseLog(adif).records[1]!.CALL).toBe('F1BÁR');
  });

  it('maps Cabrillo QSOs to ADIF-style fields', () => {
    const cabrillo = [
      'START-OF-LOG: 3.0',
      'QSO: 14000 CW 2026-10-10 1234 DL0ME 599 001 DL1AA 599 002',
    ].join('\n');
    const parsed = parseLog(cabrillo);
    expect(parsed.format).toBe('cabrillo');
    expect(parsed.records).toEqual([
      {
        FREQ: '14',
        MODE: 'CW',
        QSO_DATE: '20261010',
        TIME_ON: '1234',
        STATION_CALLSIGN: 'DL0ME',
        CALL: 'DL1AA',
        RST_SENT: '599',
        STX_STRING: '001',
        RST_RCVD: '599',
        SRX_STRING: '002',
      },
    ]);
  });

  it('selects fields from a real Cabrillo STEW-PERRY contest log', () => {
    // QSO excerpt from https://github.com/df7cb/df7cb-log/blob/0d791bac78544020a464e2918700e60ff95dd012/tlf/2021-06-19.cbr
    const actualLog = [
      'START-OF-LOG: 3.0',
      'CONTEST: STEW-PERRY',
      'QSO: 1821 CW 2021-06-19 2033 DF7CB JO31 DH1NBE 599 JN59 0',
      'END-OF-LOG:',
    ].join('\n');

    expect(selectFields(actualLog)).toEqual([
      'CALL',
      'CONTEST_ID',
      'FREQ',
      'MODE',
      'QSO_DATE',
      'RST_RCVD',
      'SRX_STRING',
      'STATION_CALLSIGN',
      'STX_STRING',
      'TIME_ON',
    ]);
    expect(parseLog(actualLog).records[0]).toMatchObject({
      STATION_CALLSIGN: 'DF7CB',
      CALL: 'DH1NBE',
      STX_STRING: 'JO31',
      RST_RCVD: '599',
      SRX_STRING: 'JN59',
      CONTEST_ID: 'STEW-PERRY',
    });
  });

  it('reads IARU R1 EDI QSO records', () => {
    // QSO excerpt from https://github.com/df7cb/df7cb-log/blob/0d791bac78544020a464e2918700e60ff95dd012/tlf/2022-07-03-darc_vhf.edi
    const edi = [
      '[REG1TEST;1]',
      'TName=Test',
      'PBand=144 MHz',
      '[QSORecords;1]',
      '220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;91;;N;N;',
    ].join('\n');
    const parsed = parseLog(edi);
    expect(parsed.format).toBe('edi');
    expect(parsed.records[0]).toMatchObject({
      CALL: 'DL7ATR',
      MODE: 'SSB',
      QSO_DATE: '20220703',
      TIME_ON: '0959',
      GRIDSQUARE: 'JO30DO',
      BAND: '2m',
    });
    expect(selectFields(edi)).toEqual([
      'BAND',
      'CALL',
      'CONTEST_ID',
      'FREQ',
      'GRIDSQUARE',
      'MODE',
      'QSO_DATE',
      'RST_RCVD',
      'RST_SENT',
      'SRX_STRING',
      'STX_STRING',
      'TIME_ON',
    ]);
  });

  it.each([
    ['50 MHz', '6m', '50'],
    ['144 MHz', '2m', '144'],
    ['145 MHz', '2m', '145'],
    ['435 MHz', '70cm', '435'],
    ['1.3 GHz', '23cm', '1300'],
    ['10 GHz', '3cm', '10000'],
    ['144', '2m', '144'],
    ['432', '70cm', '432'],
    ['1,3 GHz', '23cm', '1300'],
  ])(
    'copies EDI station headers and %s band into every contact',
    (band, expectedBand, expectedFrequency) => {
      const edi = [
        '[REG1TEST;1]',
        'PCall=OK1KEO/P',
        'PWWLo=JN79NU',
        `PBand=${band}`,
        '[QSORecords;2]',
        '220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;91;;N;N;',
        '220703;1001;DL0VR;1;59;002;59;086;;JO31MH;30;;N;;',
      ].join('\r\n');
      const records = parseLog(new TextEncoder().encode(edi)).records;
      expect(records).toHaveLength(2);
      for (const record of records) {
        expect(record).toMatchObject({
          STATION_CALLSIGN: 'OK1KEO/P',
          MY_GRIDSQUARE: 'JN79NU',
          BAND: expectedBand,
        });
        expect(record.FREQ).toBe(expectedFrequency);
      }
      expect(selectFields(edi)).toEqual([
        'BAND',
        'CALL',
        'FREQ',
        'GRIDSQUARE',
        'MODE',
        'MY_GRIDSQUARE',
        'QSO_DATE',
        'RST_RCVD',
        'RST_SENT',
        'SRX_STRING',
        'STATION_CALLSIGN',
        'STX_STRING',
        'TIME_ON',
      ]);
    },
  );

  it('does not invent absent EDI station headers', () => {
    const edi =
      '[REG1TEST;1]\nPCall=\nPWWLo=\nPBand=\n[QSORecords;1]\n220703;0959;DL7ATR;1;59;001;59;102;;JO30DO;';
    const record = parseLog(edi).records[0];
    expect(record).not.toHaveProperty('STATION_CALLSIGN');
    expect(record).not.toHaveProperty('MY_GRIDSQUARE');
    expect(record).not.toHaveProperty('BAND');
    expect(record).not.toHaveProperty('FREQ');
  });

  it.each(['unknown', '999 MHz'])('reports an unsupported EDI band %s', (band) => {
    expect(() => parseLog(`[REG1TEST;1]\nPBand=${band}\n[QSORecords;0]`)).toThrow(/EDI PBand/);
  });

  it('allows callers to supply a format when detection is ambiguous', () => {
    expect(parseLog('<CALL:5>DL1AA<EOR>', 'adif').records).toHaveLength(1);
  });

  it('rejects invalid UTF-8 and undetectable formats', () => {
    expect(() => parseLog(new Uint8Array([0xff, 0xfe]))).toThrow('valid UTF-8');
    expect(() => parseLog('just text')).toThrow('Unable to detect');
  });

  it('handles zero-length ADIF control tags and nonstandard numeric bands', () => {
    expect(parseLog('<PROGRAMID:4>Test<EOH:0><CALL:5>DL1AA<BAND:3>144<EOR:0>').records).toEqual([
      { CALL: 'DL1AA', BAND: '2m', FREQ: '144' },
    ]);
  });

  it.each([
    ['40m', 'CW', '7'],
    ['80m', 'SSB', '3.7'],
    ['80m', 'LSB', '3.7'],
    ['80m', 'CW', '3.5'],
    ['80m', 'MFSK', '3.5'],
    ['2m', 'CW', '144'],
    ['2m', 'FM', '145'],
  ])('fills missing frequency on %s in %s mode', (band, mode, frequency) => {
    const record = parseLog(`<BAND:${band.length}>${band}<MODE:${mode.length}>${mode}<EOR>`, 'adif')
      .records[0];
    expect(record.FREQ).toBe(frequency);
  });

  it('preserves an explicitly supplied frequency', () => {
    const record = parseLog('<BAND:3>80m<MODE:3>SSB<FREQ:3>3.8<EOR>', 'adif').records[0];
    expect(record.FREQ).toBe('3.8');
  });

  it('does not interpret EOR text inside a length-delimited field', () => {
    expect(parseLog('<COMMENT:5><EOR><CALL:5>DL1AA<EOR>').records).toEqual([
      { COMMENT: '<EOR>', CALL: 'DL1AA' },
    ]);
  });

  it.each([
    '<CALL:5>DL1AA',
    '<CALL:x>DL1AA<EOR>',
    '<CALL:999>DL1AA<EOR>',
    '<CALL:5>DL1AA<QSO_DATE:8>20260230<EOR>',
    '<CALL:5>DL1AA<TIME_ON:4>2460<EOR>',
  ])('rejects malformed or incomplete ADIF instead of partially converting it', (text) => {
    expect(() => parseLog(text, 'adif')).toThrow();
  });

  it('handles a blank own callsign in Cabrillo without shifting reports', () => {
    const parsed = parseLog(
      'START-OF-LOG: 3.0\nQSO:   144 CW 2021-11-06 1718               599 001    OL3Z          599 192    0',
    );
    expect(parsed.records[0]).toMatchObject({
      BAND: '2m',
      STATION_CALLSIGN: '',
      RST_SENT: '599',
      STX_STRING: '001',
      CALL: 'OL3Z',
      RST_RCVD: '599',
      SRX_STRING: '192',
    });
    expect(parsed.records[0].FREQ).toBe('144');
  });

  it('keeps received serial 1 when it is not a transmitter ID', () => {
    expect(
      parseLog('QSO: 7000 CW 2026-10-10 1234 DL0ME 599 1 DL1AA 599 1').records[0].SRX_STRING,
    ).toBe('1');
  });

  it.each(['EO60MF', 'OL50DJ', 'OM77PA', 'AN43HU', 'AO25AH', 'OL44DJ', 'OL80TN'])(
    'does not mistake special-event callsign %s for a locator',
    (call) => {
      expect(
        parseLog(`QSO: 7000 CW 2026-10-10 1234 DL0ME 599 001 ${call} 599 002`).records[0].CALL,
      ).toBe(call);
    },
  );

  it.each([
    ['1', 'SSB'],
    ['2', 'CW'],
    ['3', 'SSB'],
    ['4', 'CW'],
    ['5', 'AM'],
    ['6', 'FM'],
    ['7', 'MFSK'],
    ['8', 'SSTV'],
    ['9', 'ATV'],
  ])('maps EDI mode %s according to IARU R1', (code, expected) => {
    expect(
      parseLog(`[REG1TEST;1]\n[QSORecords;1]\n261010;1234;DL1AA;${code};59;001;59;002;;JO70AA;;;;;`)
        .records[0].MODE,
    ).toBe(expected);
  });

  it('uses the EDI header frequency for 2 m QSOs, including FM', () => {
    const record = parseLog(
      '[REG1TEST;1]\nPBand=144 MHz\n[QSORecords;1]\n261010;1234;DL1AA;6;59;001;59;002;;JO70AA;;;;;',
    ).records[0];
    expect(record).toMatchObject({ BAND: '2m', MODE: 'FM', FREQ: '144' });
  });

  it('accepts the older EDI layout without a received-exchange column', () => {
    expect(
      parseLog(
        '[REG1TEST;1]\nPBand=144\n[QSORecords;1]\n261010;1234;DL1AA;1;59;001;59;002;JO70AA;2;;N;;',
      ).records[0].GRIDSQUARE,
    ).toBe('JO70AA');
  });

  it('rejects an EDI record count mismatch', () => {
    expect(() =>
      parseLog('[REG1TEST;1]\n[QSORecords;2]\n261010;1234;DL1AA;1;59;001;59;002;;JO70AA;;;;;'),
    ).toThrow('declares 2 QSOs but contains 1');
  });
});

describe('supported log formats', () => {
  it('lists the formats from the project specification', () => {
    expect(supportedLogFormats).toEqual(['adif', 'cabrillo', 'edi']);
  });
});
